// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { measuredFit, widestToTry } from "../../../main/frontend/graph-explorer/toolbar-fit.ts";

// The graph toolbar shows labels while everything fits on one row with them, then icons while those fit, and then its
// compact form (history and the Values and Labels switches in the Tools menu): always one row, never wrapping.
const LABELS = 0;
const ICONS = 1;
const COMPACT = 2;
const fresh = { level: LABELS, widths: [] };

test("labels stay while the labelled toolbar fits its width", () => {
  assert.deepEqual(measuredFit(fresh, 1300, 1150), { level: LABELS, widths: [1150] });
  assert.deepEqual(measuredFit(fresh, 1150, 1150), { level: LABELS, widths: [1150] });
});

test("a toolbar wider than its row takes the next step and remembers how wide it was", () => {
  assert.deepEqual(measuredFit(fresh, 1100, 1150), { level: ICONS, widths: [1150] });
  assert.deepEqual(measuredFit({ level: ICONS, widths: [1150] }, 1100, 808), { level: ICONS, widths: [1150, 808] });
  assert.deepEqual(measuredFit({ level: ICONS, widths: [1150] }, 726, 764), { level: COMPACT, widths: [1150, 764] });
  assert.deepEqual(measuredFit({ level: COMPACT, widths: [1150, 764] }, 300, 330), { level: COMPACT, widths: [1150, 764, 330] },
    "the compact form is the last step");
});

test("a toolbar goes back to the widest step that fitted this width when last measured", () => {
  const compact = { level: COMPACT, widths: [1150, 764] };
  assert.equal(widestToTry(compact, 700), COMPACT);
  assert.equal(widestToTry(compact, 764), ICONS);
  assert.equal(widestToTry(compact, 1149), ICONS);
  assert.equal(widestToTry(compact, 1150), LABELS);
  assert.equal(widestToTry({ level: ICONS, widths: [] }, 900), LABELS, "never measured with labels: try them");
  assert.equal(widestToTry({ level: COMPACT, widths: [1150] }, 900), ICONS, "never measured with icons: try them");
});

test("a narrow panel takes the steps like any other: there is no second row of views", () => {
  assert.deepEqual(measuredFit(fresh, 640, 1400), { level: ICONS, widths: [1400] });
  assert.equal(widestToTry({ level: COMPACT, widths: [] }, 640), LABELS, "never measured: labels are tried first");
});
